using System;using System.IO;using System.Drawing;
class IconProbe{static Bitmap Decode(string value){if(value==null||!value.StartsWith("data:image/png;base64,"))throw new Exception("Missing PNG icon");using(var stream=new MemoryStream(Convert.FromBase64String(value.Substring(22))))using(var image=new Bitmap(stream))return new Bitmap(image);}
static void Main(string[] args){try{Run(args);}catch(Exception e){Console.WriteLine(e.GetType().FullName+": "+e.Message);Environment.Exit(1);}}static void Run(string[] args){using(var actual=Decode(FluentAppIcons.Read(args[0])))using(var expected=new Bitmap(args[1])){if(actual.Width!=expected.Width||actual.Height!=expected.Height)throw new Exception("Icon dimensions differ");if(FluentAppIcons.Read(args[0])!="data:image/png;base64,"+Convert.ToBase64String(File.ReadAllBytes(args[1])))throw new Exception("Wrong asset bytes");actual.Save(args[2],System.Drawing.Imaging.ImageFormat.Png);Console.WriteLine("PASS: package executable matched; expected unplated icon pixels; "+actual.Width+"x"+actual.Height);}
using(var fallback=Decode(FluentAppIcons.Read(Path.Combine(Environment.SystemDirectory,"notepad.exe"))))Console.WriteLine("PASS: unpackaged EXE fallback");if(FluentAppIcons.Read("missing-application.exe")!=null)throw new Exception("Missing path returned an icon");Console.WriteLine("PASS: missing application remains retryable");}}


